    fun trans(s: String, lang: String): String {
        if (lang != "ta") return s
        TA[s]?.let { return it }
        if (s.startsWith("Likely blockage: flow falling")) return "அடைப்பு இருக்கலாம்: ஓட்டம் குறைகிறது" + (if (s.contains("while level rises")) " மற்றும் நீர்மட்டம் உயர்கிறது" else "")
        val m = Regex("^Overflow predicted in about (\\d+) min\\.$").find(s)
        return if (m != null) "சுமார் " + m.groupValues[1] + " நிமிடத்தில் வழிதல் ஏற்படலாம்." else s
    }

    fun transEv(s: String, lang: String): String =
        if (lang != "ta") s else s.replace("Flow ", "ஓட்டம் ").replace(" vs baseline", " (அடிப்படையுடன்)").replace("Level +", "நீர்மட்டம் +")
            .replace(" cm", " செ.மீ").replace("Turbidity ", "கலங்கல் ").replace("Anomaly ", "அசாதாரணம் ").replace("Rain plate wet", "மழை தகடு ஈரம்")
}
